const contract = require('./control-type-contract.json')
const { meterRoute } = require('./meter-route')
// Used by both server validation and the injected editor; keep it self-contained.
function createTargetMatcher (typeContract) {
  const families = {
    range: ['number'], switch: ['boolean'], meter: ['number'], 'xy-series': ['xy-series'],
    'text-display': ['text', 'number', 'enum', 'boolean'], 'text-input': ['text'], select: ['enum']
  }
  function modes (adapter) {
    if (!families[adapter]) return []
    return ['meter', 'xy-series', 'text-display'].includes(adapter)
      ? ['read'] : ['both', 'write', 'read']
  }
  function states (target) {
    if (target.meter || target.xySeries || !['boolean', 'integer', 'float', 'enum', 'string', 'dstring'].includes(target.type)) return null
    if (Array.isArray(target.enums) && target.enums.length) {
      if (target.enums.length !== 2) return null
      const values = target.enums.map(entry => entry && typeof entry === 'object' ? entry.value : entry)
      if (values.some(value => !['boolean', 'string', 'number'].includes(typeof value) ||
        (typeof value === 'number' && !Number.isFinite(value))) || values[0] === values[1]) return null
      if (target.type === 'integer' && values.some(value => !Number.isSafeInteger(value))) return null
      if (target.type === 'float' && values.some(value => typeof value !== 'number')) return null
      if (target.type === 'boolean' && values.some(value => typeof value !== 'boolean')) return null
      if (['string', 'dstring'].includes(target.type) && values.some(value => typeof value !== 'string')) return null
      return values
    }
    if (target.type === 'boolean') return [false, true]
    if (target.type === 'integer' && Number.isSafeInteger(target.min) &&
      Number.isSafeInteger(target.max) && target.max - target.min === 1) return [target.min, target.max]
    return null
  }
  // Native readonly numeric parameters need no custom frame/manifest route.
  function meterTarget (target) {
    return target.access === 'ro' && !target.xySeries &&
      ['integer', 'float'].includes(target.type) &&
      Boolean(target.meter || (!target.enums?.length && !states(target)))
  }
  function reverse (binding = {}, write = binding.writeMeta, read = binding.readMeta) {
    if (Object.hasOwn(binding, 'stateReverse')) {
      if (typeof binding.stateReverse !== 'boolean') throw new Error('State reverse must be boolean')
      return binding.stateReverse
    }
    const point = write || read
    const mapping = write
      ? (Object.hasOwn(binding, 'writeMapping') ? binding.writeMapping : binding.writeMeta?.booleanMapping)
      : (Object.hasOwn(binding, 'readMapping') ? binding.readMapping : binding.readMeta?.booleanMapping)
    if (mapping === undefined) return false
    const values = point && states(point)
    if (!values || !mapping || typeof mapping !== 'object' || Array.isArray(mapping) ||
      !Object.hasOwn(mapping, 'falseValue') || !Object.hasOwn(mapping, 'trueValue') ||
      Object.is(mapping.falseValue, mapping.trueValue) ||
      !values.some(value => Object.is(value, mapping.falseValue)) ||
      !values.some(value => Object.is(value, mapping.trueValue))) throw new Error('Invalid two-state mapping')
    return Object.is(mapping.trueValue, values[0])
  }
  function family (target) {
    if (target.xySeries) return 'xy-series'
    if (target.controlSchemaVersion !== typeContract.schemaVersion) return null
    const definition = typeContract.types[String(target.controlType || '').toLowerCase()]
    if (!definition) return null
    const type = target.type
    if (definition.family === 'number' && !['integer', 'float'].includes(type)) return null
    if (definition.family === 'boolean' && type !== 'boolean' &&
      !(type === 'integer' && target.booleanEncoding === 'integer01' &&
        target.min === 0 && target.max === 1)) return null
    if (definition.family === 'text' && !['string', 'dstring'].includes(type)) return null
    if (definition.family === 'enum' && !['enum', 'integer', 'string'].includes(type)) return null
    return definition.family
  }
  function compatible (adapter, target, direction, candidate = {}) {
    if (adapter === 'meter' && !meterTarget(target)) return false
    if (adapter === 'range' && meterTarget(target)) return false
    if (adapter === 'xy-series' && !target.xySeries) return false
    if (target.meter && (adapter !== 'meter' || direction !== 'read' || target.access !== 'ro')) return false
    if (target.xySeries && (adapter !== 'xy-series' || direction !== 'read' || target.access !== 'ro')) return false
    if (target.kind !== 'param' || !(adapter === 'switch'
      ? states(target) : families[adapter]?.includes(family(target)))) return false
    if (direction === 'write' && ['meter', 'xy-series', 'text-display'].includes(adapter)) return false
    if (!['read', 'write'].includes(direction)) return false
    if (!(direction === 'write' ? ['wo', 'rw'] : ['ro', 'rw']).includes(target.access)) return false
    if (candidate.unit && candidate.unit !== target.unit) return false
    return true
  }
  return { family, compatible, modes, states, reverse, meterTarget }
}

const { family: targetFamily, compatible: compatibleTarget, modes: bindingModes, states: targetStates, reverse: stateReverse, meterTarget: isMeterTarget } = createTargetMatcher(contract)

function switchMapping (target, mapping, reverse = false) {
  const states = targetStates(target)
  if (!states) throw new Error('Switch target must describe exactly two distinct states')
  const result = mapping === undefined ? { falseValue: states[reverse ? 1 : 0], trueValue: states[reverse ? 0 : 1] } : mapping
  if (!result || typeof result !== 'object' || Array.isArray(result) ||
    !Object.hasOwn(result, 'falseValue') || !Object.hasOwn(result, 'trueValue') ||
    Object.is(result.falseValue, result.trueValue) ||
    !states.some(value => Object.is(value, result.falseValue)) ||
    !states.some(value => Object.is(value, result.trueValue))) throw new Error('Invalid two-state mapping')
  return { falseValue: result.falseValue, trueValue: result.trueValue }
}

function controlTypeForAdapter (adapter, target) {
  if (!compatibleTarget(adapter, target, 'read') && !compatibleTarget(adapter, target, 'write')) {
    throw new Error('Target is incompatible with this control')
  }
  if (adapter === 'meter') return 'meter'
  if (adapter === 'xy-series' && target.xySeries) return 'xy-series'
  if (adapter === 'switch') return 'mute'
  const family = targetFamily(target)
  if (family === 'number') return 'level'
  if (family === 'boolean') return 'mute'
  if (family === 'text') return 'text'
  if (family === 'enum') return 'source'
  throw new Error('Unsupported control family')
}

function targetMeta (target, onebased, booleanMapping) {
  if (typeof target.onebased !== 'boolean' && typeof onebased !== 'boolean') {
    throw new Error('Select target numbering mode')
  }
  return {
    kind: target.kind, type: target.type, access: target.access,
    onebased: typeof target.onebased === 'boolean' ? target.onebased : onebased,
    min: target.min, max: target.max, enums: target.enums,
    ...(target.booleanEncoding ? { booleanEncoding: target.booleanEncoding } : {}),
    ...(booleanMapping ? { booleanMapping: switchMapping(target, booleanMapping) } : {}),
    controlType: target.controlType, controlSchemaVersion: target.controlSchemaVersion,
    ...(target.meter ? { meter: meterRoute(target.meter), unit: target.unit || '' } : {}),
    ...(target.xySeries ? { xySeries: require('./xy-series-route').xySeriesRoute(target.xySeries) } : {}),
    ...(target.availability ? { availability: require('./device-availability').availabilityRoute(target.availability,
      typeof target.onebased === 'boolean' ? target.onebased : onebased) } : {})
  }
}

module.exports = { contract, createTargetMatcher, compatibleTarget, controlTypeForAdapter, targetFamily, targetMeta, bindingModes, targetStates, switchMapping, stateReverse, isMeterTarget }
